sect1.para:
C source code: #include<pdi.h>

intmain(intargc,char*argv[]){
PDI_init(PC_parse_path("hello_event.yml"));

PDI_event("HelloWorldEvent");

PDI_finalize();
return0;
}

sect2.para:
C source code: #include<pdi.h>

intmain(intargc,char*argv[]){
PDI_init(PC_parse_path("hello_data.yml"));
intmy_world=42;
PDI_share("world",&my_world,PDI_OUT);
//variablemy_worldissharedwithPDI

PDI_reclaim("world");
//variablemy_worldisnolongersharedwithPDI

PDI_finalize();
return0;
}

Fortran source code: callpdi_share("world",p_my_world,pdi_out)
callpdi_reclaim("world");
 is the same as: callpdi_expose("world",p_my_world,pdi_out)

Now we will try to access a descriptor we share with PDI. In this case we won't need any plugin. We want to define int and a string in our world_access.yml: data:
my_value:int
my_message:{type:array,subtype:char,size:32}

C source code: #include<pdi.h>

voidprint_secret_msg(){
int*value;
PDI_access("my_value",(void**)&value,PDI_IN);
printf("%d\n",*value);
PDI_release("my_value");

char*message;
PDI_access("my_message",(void**)&message,PDI_IN);
printf("%s\n",message);
PDI_release("my_message");
}

intmain(intargc,char*argv[]){
PDI_init(PC_parse_path("world_access.yml"));
intmy_value=42;
PDI_share("my_value",&my_value,PDI_OUT);

char*secret_msg="Watermelonisthetastiestfruit";
PDI_share("my_message",secret_msg,PDI_OUT);

print_secret_msg();

PDI_reclaim("my_message");
PDI_reclaim("my_value");

PDI_finalize();
return0;
}

C source code: #include<pdi.h>

intmain(intargc,char*argv[]){
PDI_init(PC_parse_path("hello_multi_expose.yml"));
intx=0;
floaty=0;
char*z="RGB=ReallyGawkyBiscuit";

PDI_multi_expose("event_between",
"my_int",&x,PDI_OUT,
"my_float",&y,PDI_OUT,
"my_string",&z,PDI_OUT,
NULL);

PDI_finalize();
return0;
}
